const ARROW = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="28" viewBox="0 0 22 28"><path d="M2 2 L2 22 L7.5 17 L11 26 L14.5 24.5 L11 15.8 L18.5 15.8 Z" fill="black" stroke="white" stroke-width="1.6" stroke-linejoin="round"/></svg>`;

// Screenshots omit the OS cursor; draw one so viewers can follow the pointer.
const cursorAt = (ctx, p) =>
  ctx.client.evaluate(`let c = document.getElementById("dg-doc-cursor");
    if (!c) { c = document.createElement("div"); c.id = "dg-doc-cursor";
      c.style.cssText = "position:fixed;z-index:2147483647;pointer-events:none;left:0;top:0;width:22px;height:28px;";
      c.innerHTML = ${ctx.json(ARROW)}; document.body.appendChild(c); }
    c.style.transform = "translate(" + ${p.x} + "px," + ${p.y} + "px)"; return true;`);
const removeCursor = (ctx) => ctx.client.evaluate(`document.getElementById("dg-doc-cursor")?.remove(); return true;`);

const FRAME = 0.06; // seconds per motion frame
const ease = (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2);

// A pointer that moves, clicks, drags and types at human pace, recording frames as it goes.
const human = (ctx, fr, start) => {
  let pos = start;
  const send = (type, p, extra = {}) =>
    ctx.client.send("Input.dispatchMouseEvent", { type, x: p.x, y: p.y, button: "left", clickCount: 1, ...extra });
  const moveTo = async (to, ms = 600, buttons = 0) => {
    const steps = Math.max(2, Math.round(ms / 1000 / FRAME));
    const from = pos;
    for (let i = 1; i <= steps; i++) {
      const t = ease(i / steps);
      pos = { x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t };
      await send("mouseMoved", pos, buttons ? { buttons: 1 } : { button: "none" });
      await cursorAt(ctx, pos);
      await fr.add("move", FRAME);
    }
  };
  return {
    get pos() { return pos; },
    moveTo,
    async hold(sec) { await cursorAt(ctx, pos); await fr.add("hold", sec); },
    async click(to, { ms = 600, after = 0.5 } = {}) {
      await moveTo(to, ms);
      await fr.add("aim", 0.2);
      await send("mousePressed", pos, { buttons: 1 });
      await send("mouseReleased", pos);
      await sleep(350);
      await cursorAt(ctx, pos);
      await fr.add("clicked", after);
    },
    async drag(from, to, ms = 1100) {
      await moveTo(from, 350);
      await fr.add("aim", 0.25);
      await send("mousePressed", pos, { buttons: 1 });
      await moveTo(to, ms, 1);
      await send("mouseReleased", pos);
      await sleep(500);
    },
    async type(text, perChar = 0.11) {
      for (const ch of text) {
        await ctx.client.typeText(ch);
        await fr.add("type", perChar);
      }
    },
  };
};

const shapeCenter = (ctx, id) =>
