const dotToward = (ctx, to) =>
  ctx.client.evaluate(`const ed = window.__dgEd; const b = ed.getShapePageBounds(${ctx.json(to)});
    const t = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => { const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; });
    dots.sort((a, c) => Math.hypot(a.x - t.x, a.y - t.y) - Math.hypot(c.x - t.x, c.y - t.y));
    return dots[0] ?? null;`);
const MENU = `(() => { const h = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type"); return h?.closest(".pointer-events-auto"); })()`;
